mod anchorlaw;
fn main(){println!("vertices\tell\tcases\tpositive_rank\tclosed_cases\tzero_size_cases");for n in 1usize..=4{for ell in [3,5,1000003]{let edges:Vec<_>=(0..n).flat_map(|i|(i+1..n).map(move|j|(i,j))).collect();let slots=edges.len()+n;let mut count=0u64;let mut positive=0;let mut closed=0;let mut zero_size=0;for mut config in 0usize..3usize.pow(slots as u32){let mut cols=vec![];let mut anchors=vec![];for k in 0..slots{let state=config%3;config/=3;if state==0{continue}let mut v=vec![0;n];if k<edges.len(){let(i,j)=edges[k];v[i]=1;v[j]=ell-1}else{v[k-edges.len()]=1}cols.push(v);anchors.push(state==2)}let b:Vec<Vec<u64>>=(0..n).map(|i|cols.iter().map(|v|v[i]).collect()).collect();let(r,_,c,_,z)=anchorlaw::check(&b,&anchors,ell);count+=1;positive+=u64::from(r>0);closed+=u64::from(c>0);zero_size+=z as u64;}println!("{n}\t{ell}\t{count}\t{positive}\t{closed}\t{zero_size}");}}}
